// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract Callee {
    uint256 public marker;
    function receiveBytes(bytes memory) external payable {
        marker = 1;
    }
}

contract InvMutTest is Test {
    Proxy c;
    function setUp() public { c = new Proxy(); }
    function testFuzz_property(uint256 seed, uint8 dataLen) public {
        bound(dataLen, 1, 128);

        Callee callee = new Callee();

        bytes memory data = new bytes(dataLen);
        for (uint256 i = 0; i < dataLen; i++) {
            data[i] = bytes1(uint8(seed >> (i * 8)));
        }

        bytes memory payload = abi.encodeWithSelector(Callee.receiveBytes.selector, data);

        c.forward(address(callee), payload);

        uint256 m = callee.marker();
        assertTrue(m == 1);
    }
}
